function i(){return{tasks:[{text:"Как решающее дерево делит пространство признаков?",type:"choice",answer:"На прямоугольные области, в каждой из которых предсказание постоянно",options:["На прямоугольные области, в каждой из которых предсказание постоянно","На произвольные круглые кластеры","Оно вообще не делит пространство признаков","На области с линейно меняющимся предсказанием"],hint:"Дерево приближает зависимость кусочно-постоянной функцией",difficulty:"Легко"},{text:"Что содержит внутренняя вершина решающего дерева?",type:"choice",answer:"Предикат (условие), по которому объект уходит в одно из двух поддеревьев",options:["Предикат (условие), по которому объект уходит в одно из двух поддеревьев","Готовое предсказание из множества значений таргета","Список всех обучающих объектов","Значение функции потерь модели"],hint:"Готовое предсказание хранится в листьях, а не во внутренних вершинах",difficulty:"Легко"},{text:"Почему построение глобально оптимального решающего дерева считается сложной задачей?",type:"choice",answer:"Это NP-полная задача — количество возможных структур дерева растёт экспоненциально с глубиной",options:["Это NP-полная задача — количество возможных структур дерева растёт экспоненциально с глубиной","Потому что для любого дерева нельзя посчитать ошибку на обучающей выборке","Потому что решающие деревья вообще не поддаются математическому анализу","Задача простая, оптимальное дерево всегда строится быстро"],hint:"Даже для дерева глубины 1 перебор возможен, а дальше сложность резко растёт",difficulty:"Средне"},{text:"Как жадный алгоритм строит решающее дерево?",type:"choice",answer:"На каждом шаге выбирает локально лучшее разбиение, не пересматривая его позже",options:["На каждом шаге выбирает локально лучшее разбиение, не пересматривая его позже","Перебирает все возможные деревья и выбирает лучшее","Строит дерево снизу вверх, начиная с листьев","Случайным образом выбирает предикаты в каждой вершине"],hint:"Это разменивает гарантию оптимума на вычислимость за разумное время",difficulty:"Средне"},{text:"Что такое impurity (неопределённость) узла?",type:"choice",answer:"Минимальная средняя ошибка, если предсказывать в этом узле одной константой",options:["Минимальная средняя ошибка, если предсказывать в этом узле одной константой","Общее количество объектов, попавших в узел","Глубина узла в дереве","Число возможных порогов для разбиения узла"],hint:"Чем хуже константа описывает данные в узле, тем выше impurity",difficulty:"Средне"},{text:"Какое разбиение жадный алгоритм выбирает на каждом шаге?",type:"choice",answer:"То, что даёт максимальный прирост информации (Gain) относительно текущей impurity",options:["То, что даёт максимальный прирост информации (Gain) относительно текущей impurity","Первое найденное разбиение, удовлетворяющее любому условию","Разбиение, дающее наибольшее число объектов в правом поддереве","Случайно выбранное из всех возможных разбиений"],hint:"Gain = Impurity(S) минус взвешенная сумма impurity дочерних узлов",difficulty:"Средне"},{text:"Какой критерий impurity используют чаще всего для регрессии?",type:"choice",answer:"MSE — impurity равна дисперсии таргета, оптимальный ответ в листе — среднее значение",options:["MSE — impurity равна дисперсии таргета, оптимальный ответ в листе — среднее значение","Индекс Джини","Энтропия","Ошибка неверной классификации"],hint:"Джини и энтропия — критерии для задач классификации",difficulty:"Средне"},{text:"Что показывает высокая энтропия в узле дерева?",type:"choice",answer:"Классы в узле распределены близко к равномерному — высокая непредсказуемость",options:["Классы в узле распределены близко к равномерному — высокая непредсказуемость","В узле остались объекты только одного класса","В узле нет ни одного объекта","Узел является листом дерева"],hint:"Энтропия минимальна (равна нулю), когда все объекты в узле одного класса",difficulty:"Сложно"},{text:"Как решающее дерево обрабатывает пропущенные значения признака при обучении?",type:"choice",answer:"После выбора разбиения объекты с пропуском отправляют в оба поддерева с весами",options:["После выбора разбиения объекты с пропуском отправляют в оба поддерева с весами","Все объекты с пропусками полностью удаляются из обучающей выборки","Пропуски автоматически заменяются нулём перед построением дерева","Дерево вообще не может обучаться, если есть пропуски"],hint:"Веса равны долям |S_L|/|S| и |S_R|/|S|, они же используются и при предсказании",difficulty:"Сложно"},{text:"В чём разница между pre-pruning и post-pruning?",type:"choice",answer:"Pre-pruning ограничивает рост дерева заранее, post-pruning сначала строит полное дерево, а потом обрезает лишние ветви по валидации",options:["Pre-pruning ограничивает рост дерева заранее, post-pruning сначала строит полное дерево, а потом обрезает лишние ветви по валидации","Это два названия одного и того же метода регуляризации","Pre-pruning применяется только к регрессии, post-pruning — только к классификации","Post-pruning всегда быстрее и проще, чем pre-pruning"],hint:"max_depth и min_samples_leaf — примеры pre-pruning",difficulty:"Средне"}]}}export{i as default};
